import json
import itertools

def compute_itinerary():
    # Input variables (constraints)
    total_days = 10
    cities = ["London", "Santorini", "Istanbul"]
    required_stay = {"London": 3, "Santorini": 6, "Istanbul": 3}
    conference_city = "Santorini"
    conference_days = [5, 10]
    direct_flights_input = [("Istanbul", "London"), ("London", "Santorini")]  # Undirected

    # Build undirected flight graph as set of frozensets for easy lookup
    direct_flights = {frozenset(pair) for pair in direct_flights_input}

    def has_direct(u, v):
        return frozenset((u, v)) in direct_flights

    # Validate basic inputs
    if conference_city not in cities:
        return {"itinerary": []}

    # Enumerate sequences of visiting 3 distinct cities ending in the conference city
    sequences = []
    for seq in itertools.permutations(cities, 3):
        if seq[-1] != conference_city:
            continue
        # Must have direct flights for the two legs
        if has_direct(seq[0], seq[1]) and has_direct(seq[1], seq[2]):
            sequences.append(seq)

    # Find feasible sequences that meet stay counts and conference-day constraints
    candidates = []
    for seq in sequences:
        A, B, C = seq  # Start -> middle -> end
        # Number of flights is len(seq)-1 = 2; overlapping days = 2
        # For a chain with two flights on days a and b (a<b):
        # Days in A = a
        # Days in B = b - a + 1
        # Days in C = total_days - b + 1
        # Solve for a and b:
        a_from_A = required_stay[A]
        b_from_B = a_from_A + required_stay[B] - 1
        b_from_C = total_days - required_stay[C] + 1
        if b_from_B != b_from_C:
            continue
        a, b = a_from_A, b_from_B
        if not (1 <= a < b <= total_days):
            continue
        # Conference days must all be in C, i.e., >= b
        if not all(b <= d <= total_days for d in conference_days):
            continue

        # Verify counts by simulating occupancy by day
        day_cities = {}
        for d in range(1, total_days + 1):
            if d < a:
                day_cities[d] = {A}
            elif d == a:
                day_cities[d] = {A, B}
            elif a < d < b:
                day_cities[d] = {B}
            elif d == b:
                day_cities[d] = {B, C}
            else:  # d > b
                day_cities[d] = {C}

        # Count days per city
        count_per_city = {city: 0 for city in cities}
        for d in range(1, total_days + 1):
            for city in day_cities[d]:
                count_per_city[city] += 1

        if all(count_per_city[city] == required_stay[city] for city in cities):
            # Feasible candidate
            candidates.append((seq, a, b))

    # Choose an "optimal" candidate:
    # Prefer earliest arrival to the conference city (smallest b), then earliest first flight (smallest a)
    if not candidates:
        return {"itinerary": []}
    candidates.sort(key=lambda x: (x[2], x[1]))
    (A, B, C), a, b = candidates[0]

    # Construct itinerary segments; note overlapping boundaries per flight-day rule
    itinerary = [
        {"day_range": f"Day 1-{a}", "place": A},
        {"day_range": f"Day {a}-{b}", "place": B},
        {"day_range": f"Day {b}-{total_days}", "place": C},
    ]

    return {"itinerary": itinerary}

if __name__ == "__main__":
    result = compute_itinerary()
    print(json.dumps(result))
